document.querySelectorAll(".tab").forEach(e=>{e.addEventListener("click",()=>{document.querySelectorAll(".tab").forEach(e=>{e.classList.remove("active"),e.setAttribute("aria-selected","false")}),document.querySelectorAll(".toggle-pane").forEach(e=>e.classList.remove("active")),e.classList.add("active"),e.setAttribute("aria-selected","true"),document.getElementById(e.dataset.pane).classList.add("active")})});